// The runtime every generated facade carries, copied verbatim into its `src/internal/effectify.ts`: the types that
// derive a facade from upstream's own types, and the few functions that turn an upstream object into its facade.
// It depends on `effect` alone, so a facade package needs nothing of the engine at run time.

import { Effect, Queue, Schema, type Scope, Stream } from "effect";

/** An upstream handle type and its facade, with whether acquiring it opens a scope (it has a release method). */
export type HandleEntry = readonly [upstream: unknown, facade: unknown, scoped: boolean];

/** Every signature of an overloaded function as a union of single-signature functions (up to 12; TypeScript matches the last ones). */
export type Overloads<F> = F extends {
	(...args: infer A1): infer R1;
	(...args: infer A2): infer R2;
	(...args: infer A3): infer R3;
	(...args: infer A4): infer R4;
	(...args: infer A5): infer R5;
	(...args: infer A6): infer R6;
	(...args: infer A7): infer R7;
	(...args: infer A8): infer R8;
	(...args: infer A9): infer R9;
	(...args: infer A10): infer R10;
	(...args: infer A11): infer R11;
	(...args: infer A12): infer R12;
}
	?
			| ((...args: A1) => R1)
			| ((...args: A2) => R2)
			| ((...args: A3) => R3)
			| ((...args: A4) => R4)
			| ((...args: A5) => R5)
			| ((...args: A6) => R6)
			| ((...args: A7) => R7)
			| ((...args: A8) => R8)
			| ((...args: A9) => R9)
			| ((...args: A10) => R10)
			| ((...args: A11) => R11)
			| ((...args: A12) => R12)
	: never;

// `any` satisfies every conditional: a signature returning it stays as it is, and counts as neither async nor stream.
type IsAny<T> = 0 extends 1 & T ? true : false;

type UnionToIntersection<U> = (U extends unknown ? (u: U) => void : never) extends (i: infer I) => void ? I : never;

/** The facade of `V` when `H` lists it as a handle, else `V` itself. */
export type Lift<V, H extends HandleEntry> = [HandleOf<V, H>] extends [never] ? V : HandleOf<V, H>[1];

// `any` would match every handle: a value typed `any` stays `any`.
type HandleOf<V, H extends HandleEntry> = IsAny<V> extends true ? never : H extends HandleEntry ? ([V] extends [H[0]] ? H : never) : never;

// A handle wins over an async iterable: sharp's `Sharp` is a Node `Duplex`, iterable, and still the handle the
// facade wraps.
type IsHandle<V, H extends HandleEntry> = [HandleOf<V, H>] extends [never] ? false : true;

/** What one resolved value becomes in an `Effect`: its facade, needing a `Scope` when the handle is scoped. */
export type Resolved<V, E, H extends HandleEntry> = [HandleOf<V, H>] extends [never]
	? Effect.Effect<V, E>
	: HandleOf<V, H>[2] extends true
		? Effect.Effect<HandleOf<V, H>[1], E, Scope.Scope>
		: Effect.Effect<HandleOf<V, H>[1], E>;

/** What a method's result becomes in a handle's facade: a promise an `Effect`, an async iterable a `Stream`, a handle its facade. */
export type MethodResult<R, E, H extends HandleEntry> = IsAny<R> extends true
	? R
	: R extends PromiseLike<infer V>
		? Resolved<V, E, H>
		: IsHandle<R, H> extends true
			? Lift<R, H>
			: R extends AsyncIterable<infer V>
				? Stream.Stream<V, E>
				: R;

/** One method signature of a handle in facade form. */
export type MethodSignature<F, E, H extends HandleEntry> = F extends (...args: infer A) => infer R
	? IsCallbackStyle<A, R> extends true
		? never
		: (...args: A) => MethodResult<R, E, H>
	: never;

/**
 * Types a generic upstream method as the facade calls it, its type parameters kept: TypeScript carries them through
 * a generic call (higher-order inference), never through a mapped type, so a method whose signature names types
 * upstream does not export still has its exact type. Generated code calls it only in a function that never runs, to
 * read the type with `typeof`; at run time `effectify` wraps the method like any other.
 */
export const lifted =
	<E, H extends HandleEntry>() =>
	<A extends ReadonlyArray<unknown>, R>(method: (...args: A) => R): ((...args: A) => MethodResult<R, E, H>) =>
		method as never;

/** One exported function in facade form: like a method, but a synchronous call becomes an `Effect` too (it may throw). */
export type FunctionSignature<F, E, H extends HandleEntry> = F extends (...args: infer A) => infer R
	? IsCallbackStyle<A, R> extends true
		? never
		: (...args: A) => IsAny<R> extends true
				? Effect.Effect<R, E>
				: R extends PromiseLike<infer V>
					? Resolved<V, E, H>
					: IsHandle<R, H> extends true
						? Resolved<R, E, H>
						: R extends AsyncIterable<infer V>
							? Stream.Stream<V, E>
							: Resolved<R, E, H>
	: never;

// A signature whose last parameter is a function and that returns nothing reports its result through that callback:
// its promise twin is the facade's, so it is left out.
type IsCallbackStyle<A extends ReadonlyArray<unknown>, R> = A extends readonly [...ReadonlyArray<unknown>, infer Last]
	? Last extends (...args: never) => unknown
		? [R] extends [void]
			? true
			: false
		: false
	: false;

/**
 * A method with every overload kept, each in facade form. A method whose every overload takes a trailing callback and
 * returns nothing, and which the generator does not list as reporting through it (`CallbackMethod`), takes the
 * callback as an argument like any other (a key handler): it stays as upstream types it.
 */
export type EffectMethod<F, E, H extends HandleEntry> = [MethodSignature<Overloads<F>, E, H>] extends [never]
	? F
	: UnionToIntersection<MethodSignature<Overloads<F>, E, H>>;

/** What a trailing callback reports: the value after its error (`(error, value)`), or nothing (`done()`). */
type CallbackValue<L> = L extends (first: never, ...rest: infer Rest) => unknown ? (Rest extends readonly [infer V, ...ReadonlyArray<unknown>] ? V : void) : void;

// The parameters before the last and the last, which may be optional (`write(data, callback?)`).
type SplitLast<A extends ReadonlyArray<unknown>> = A extends readonly [...infer Init, infer Last]
	? readonly [Init, Last]
	: Required<A> extends readonly [...ReadonlyArray<unknown>, infer Last]
		? A extends readonly [...infer Init, (Last | undefined)?]
			? readonly [Init, Last]
			: never
		: never;

// One overload that reports through its trailing callback, as an Effect of what the callback reports.
type CallbackSignature<F, E, H extends HandleEntry> = F extends (...args: infer A) => infer R
	? [R] extends [void]
		? SplitLast<A> extends readonly [infer Init extends ReadonlyArray<unknown>, infer Last]
			? NonNullable<Last> extends (...args: never) => unknown
				? (...args: Init) => Resolved<CallbackValue<NonNullable<Last>>, E, H>
				: never
			: never
		: never
	: never;

/**
 * A method that reports through its trailing callback (`node`: error first, then the result; `done`: called when the
 * work is done), as an `Effect` of what the callback reports: the generator lists such methods in `HandleSpec.callback`.
 */
export type CallbackMethod<F, E, H extends HandleEntry> = UnionToIntersection<CallbackSignature<Overloads<F>, E, H>>;

/**
 * An exported function with every overload kept, each in facade form. A function whose every overload takes a
 * trailing callback and returns nothing takes it as an argument (a handler): its call is an `Effect` like any other.
 */
export type EffectFunction<F, E, H extends HandleEntry> = [FunctionSignature<Overloads<F>, E, H>] extends [never]
	? UnionToIntersection<Overloads<F> extends (...args: infer A) => infer R ? (...args: A) => Resolved<R, E, H> : never>
	: UnionToIntersection<FunctionSignature<Overloads<F>, E, H>>;

/** The keys of `T` whose value is a function. */
export type MethodKeys<T> = { [K in keyof T]-?: T[K] extends (...args: never) => unknown ? K : never }[keyof T] & string;

/**
 * A handle's facade: each method `K` of `T` in facade form, and the upstream object. `K` is the generator's list of
 * the methods the target declares itself (not those it inherits from Node's streams or emitters).
 */
export type Effectified<
	T,
	E,
	H extends HandleEntry,
	K extends MethodKeys<T> = MethodKeys<T>,
	P extends keyof T = never,
	C extends K = never,
> = {
	readonly [M in Exclude<K, C>]: EffectMethod<T[M], E, H>;
} & { readonly [M in C]: CallbackMethod<T[M], E, H> } & { readonly [Q in P]: Lift<T[Q], H> } & { readonly upstream: T };

/** The methods of `T` with an overload that returns a promise (or any thenable). */
export type AsyncKeys<T> = { [K in MethodKeys<T>]: [Returning<Overloads<T[K]>, PromiseLike<unknown>>] extends [never] ? never : K }[MethodKeys<T>];

/** The methods of `T` with an overload that returns an async iterable that is no handle of `H`. */
export type StreamKeys<T, H extends HandleEntry = never> = {
	[K in MethodKeys<T>]: [StreamOf<Returning<Overloads<T[K]>, AsyncIterable<unknown>>, H>] extends [never] ? never : K;
}[MethodKeys<T>];

type StreamOf<F, H extends HandleEntry> = F extends (...args: never) => infer R ? (IsHandle<R, H> extends true ? never : F) : never;

/** The signatures of `F` whose result is an `R` (and not `any`). */
type Returning<F, R> = F extends (...args: never) => infer Result ? (IsAny<Result> extends true ? never : Result extends R ? F : never) : never;

/**
 * Exactly the async methods of `T`. A generated spec `satisfies` it, so when upstream adds, removes or changes an
 * async method of a wrapped handle the facade stops compiling and names the method.
 */
export type AsyncSpec<T> = { readonly [K in AsyncKeys<T>]: true };

/** Exactly the async-iterable methods of `T` (handles of `H` excepted), checked like `AsyncSpec`. */
export type StreamSpec<T, H extends HandleEntry = never> = { readonly [K in Exclude<StreamKeys<T, H>, AsyncKeys<T>>]: true };

/** What the generator knows of one handle's methods at run time; the types above say the same, and a facade checks both agree. */
export interface HandleSpec {
	/** Every method the facade wraps; the facade's type lists the same (`<Handle>Methods`). */
	readonly methods: ReadonlyArray<string>;
	/** Methods that return a promise (an `Effect`). */
	readonly async: Readonly<Record<string, true>>;
	/** Methods that return an async iterable (a `Stream`). */
	readonly stream?: Readonly<Record<string, true>>;
	/** Methods that report through a trailing callback (an `Effect`): error first (`node`), or a call when done (`done`). */
	readonly callback?: Readonly<Record<string, "node" | "done">>;
	/** Methods whose result is another handle, by the name of that handle's spec. */
	readonly returns?: Readonly<Record<string, string>>;
	/** Properties the facade reads through from upstream (live): `true`, or the handle a property holds. */
	readonly properties?: Readonly<Record<string, string | true>>;
}

/** A handle's spec as the generator writes it, and how to release it when it is scoped. */
export interface HandleKind {
	readonly name: string;
	readonly spec: HandleSpec;
	/** The method that releases the handle, for handles acquired in a scope. */
	readonly release?: string;
}

/** Maps any failure of an upstream call to the facade's error type. */
export type Classify<E> = (operation: string, cause: unknown) => E;

/** Turns `upstream` into its facade: async methods into `Effect`s, iterables into `Stream`s, handles into theirs. */
export function effectify<T extends object, E>(
	upstream: T,
	kind: HandleKind,
	kinds: Readonly<Record<string, HandleKind>>,
	classify: Classify<E>,
): Effectified<T, E, HandleEntry> {
	const facade: Record<string, unknown> = { upstream };
	for (const key of kind.spec.methods) {
		const operation = `${kind.name}.${key}`;
		// Trust boundary: the generator lists `key` as a method of `T` and the facade's types check that it is one.
		const method = (upstream as Record<string, (...args: ReadonlyArray<unknown>) => unknown>)[key];
		if (method === undefined) continue;
		const returned = kind.spec.returns?.[key];
		const into = returned === undefined ? undefined : kinds[returned];
		const reports = kind.spec.callback?.[key];
		if (reports !== undefined) {
			facade[key] = (...args: Array<unknown>) =>
				acquire(
					Effect.callback<unknown, E>((resume) => {
						const callback =
							reports === "node"
								? (error: unknown, value: unknown) => resume(error === null || error === undefined ? Effect.succeed(value) : Effect.fail(classify(operation, error)))
								: () => resume(Effect.void);
						try {
							method.apply(upstream, [...args, callback]);
						} catch (cause) {
							resume(Effect.fail(classify(operation, cause)));
						}
					}),
					into,
					kinds,
					classify,
				);
		} else if (kind.spec.async[key]) {
			facade[key] = (...args: Array<unknown>) =>
				resolve(() => method.apply(upstream, args) as PromiseLike<unknown>, operation, into, kinds, classify);
		} else if (kind.spec.stream?.[key]) {
			facade[key] = (...args: Array<unknown>) =>
				Stream.fromAsyncIterable(method.apply(upstream, args) as AsyncIterable<unknown>, (cause) => classify(operation, cause));
		} else if (into !== undefined) {
			facade[key] = (...args: Array<unknown>) => wrap(method.apply(upstream, args), into, kinds, classify);
		} else {
			facade[key] = (...args: Array<unknown>) => method.apply(upstream, args);
		}
	}
	for (const [key, held] of Object.entries(kind.spec.properties ?? {})) {
		const into = held === true ? undefined : kinds[held];
		Object.defineProperty(facade, key, {
			enumerable: true,
			// Read through on every access: upstream's fields change (a job's progress, a browser's connected state).
			get: () => {
				const value = (upstream as Record<string, unknown>)[key];
				return into === undefined ? value : wrap(value, into, kinds, classify);
			},
		});
	}
	// The object is built to the shape `Effectified` describes, key by key, from the same spec.
	return facade as Effectified<T, E, HandleEntry>;
}

/** An exported function in facade form: each call runs as an `Effect` (see `call`), every overload kept. */
export function entry<F extends (...args: never) => unknown, E, H extends HandleEntry>(
	fn: F,
	operation: string,
	into: HandleKind | undefined,
	kinds: Readonly<Record<string, HandleKind>>,
	classify: Classify<E>,
): EffectFunction<F, E, H> {
	const invoke = fn as unknown as (...args: Array<unknown>) => unknown;
	// `EffectFunction` describes, overload by overload, what `call` does with each result.
	return ((...args: Array<unknown>) => call(() => invoke(...args), operation, into, kinds, classify)) as unknown as EffectFunction<F, E, H>;
}

/** An exported class in facade form: constructing runs as an `Effect` of the instance's facade, scoped if releasable. */
export function construct<C extends abstract new (...args: never) => unknown, E, H extends HandleEntry>(
	Class: C,
	operation: string,
	into: HandleKind,
	kinds: Readonly<Record<string, HandleKind>>,
	classify: Classify<E>,
): (...args: ConstructorParameters<C>) => Resolved<InstanceType<C>, E, H> {
	const make = Class as unknown as new (...args: Array<unknown>) => unknown;
	// `Resolved` describes what `call` does with the instance: its facade, in a scope when the handle is releasable.
	return ((...args: Array<unknown>) => call(() => new make(...args), operation, into, kinds, classify)) as never;
}

/**
 * `entry` typed by the generator: for generic functions, whose type parameters inference through `EffectFunction`
 * would lose, the generator writes each overload out (`T`) from upstream's declaration.
 */
export function entryAs<T>(
	fn: (...args: never) => unknown,
	operation: string,
	into: HandleKind | undefined,
	kinds: Readonly<Record<string, HandleKind>>,
	classify: Classify<unknown>,
): T {
	const invoke = fn as unknown as (...args: Array<unknown>) => unknown;
	// `T` restates upstream's overloads with `call`'s results; the compiler checks it against upstream when generated.
	return ((...args: Array<unknown>) => call(() => invoke(...args), operation, into, kinds, classify)) as T;
}

/** `construct` typed by the generator: for generic classes, whose constructor parameters `ConstructorParameters` loses. */
export function constructAs<T>(
	Class: abstract new (...args: never) => unknown,
	operation: string,
	into: HandleKind,
	kinds: Readonly<Record<string, HandleKind>>,
	classify: Classify<unknown>,
): T {
	const make = Class as unknown as new (...args: Array<unknown>) => unknown;
	// As in `entryAs`: `T` restates upstream's constructors with `call`'s result.
	return ((...args: Array<unknown>) => call(() => new make(...args), operation, into, kinds, classify)) as T;
}

/** The fields every generated error has: the operation that failed, its message, the upstream code, and the cause. */
export const errorFields = {
	operation: Schema.String,
	message: Schema.String,
	code: Schema.optional(Schema.String),
	cause: Schema.Defect(),
};

/** The values of `errorFields` for a failure of `operation`. */
export function describe(operation: string, cause: unknown): { operation: string; message: string; code?: string; cause: unknown } {
	const message = cause instanceof Error ? cause.message : String(cause);
	const code = typeof cause === "object" && cause !== null ? (cause as { code?: unknown }).code : undefined;
	return typeof code === "string" ? { operation, message, code, cause } : { operation, message, cause };
}

/** Runs an exported function as an `Effect`: a promise is awaited, a synchronous call caught, a handle wrapped. */
export function call<E>(
	thunk: (signal: AbortSignal) => unknown,
	operation: string,
	into: HandleKind | undefined,
	kinds: Readonly<Record<string, HandleKind>>,
	classify: Classify<E>,
): Effect.Effect<unknown, E, Scope.Scope> {
	return Effect.suspend(() => {
		let result: unknown;
		try {
			result = thunk(new AbortController().signal);
		} catch (cause) {
			return Effect.fail(classify(operation, cause));
		}
		return isPromiseLike(result)
			? resolve(() => result as PromiseLike<unknown>, operation, into, kinds, classify)
			: acquire(Effect.succeed(result), into, kinds, classify);
	});
}

/** Awaits an upstream promise as an `Effect`, and wraps its value when it is a handle (scoped if releasable). */
function resolve<E>(
	thunk: (signal: AbortSignal) => PromiseLike<unknown>,
	operation: string,
	into: HandleKind | undefined,
	kinds: Readonly<Record<string, HandleKind>>,
	classify: Classify<E>,
): Effect.Effect<unknown, E, Scope.Scope> {
	const awaited = Effect.tryPromise({ try: thunk, catch: (cause) => classify(operation, cause) });
	return acquire(awaited, into, kinds, classify);
}

/** Wraps a produced handle; one with a release method is released when the scope closes. */
function acquire<E>(
	produced: Effect.Effect<unknown, E>,
	into: HandleKind | undefined,
	kinds: Readonly<Record<string, HandleKind>>,
	classify: Classify<E>,
): Effect.Effect<unknown, E, Scope.Scope> {
	if (into === undefined) return produced;
	const release = into.release;
	if (release === undefined) return Effect.map(produced, (value) => wrap(value, into, kinds, classify));
	return Effect.acquireRelease(produced, (value) =>
		Effect.promise(() => Promise.resolve((value as Record<string, () => unknown>)[release]?.())).pipe(Effect.ignore),
	).pipe(Effect.map((value) => wrap(value, into, kinds, classify)));
}

function wrap<E>(value: unknown, into: HandleKind, kinds: Readonly<Record<string, HandleKind>>, classify: Classify<E>): unknown {
	return typeof value === "object" && value !== null ? effectify(value, into, kinds, classify) : value;
}

function isPromiseLike(value: unknown): value is PromiseLike<unknown> {
	return typeof value === "object" && value !== null && typeof (value as { then?: unknown }).then === "function";
}

/**
 * Events of an emitter as a `Stream` of each emission's arguments, listening for as long as the stream runs. `A` is
 * the listener's parameters as upstream types them for `event`, which the generator names through upstream's `on`.
 */
export function events<A extends ReadonlyArray<unknown> = ReadonlyArray<unknown>>(emitter: object, event: string): Stream.Stream<A> {
	// The generator offers events only of handles whose types have `on`; `off` (or `removeListener`) pairs with it.
	const target = emitter as EventEmitterLike;
	return Stream.callback<A>((queue) =>
		Effect.acquireRelease(
			Effect.sync(() => {
				const listener = (...args: ReadonlyArray<unknown>) => {
					// Upstream calls the listener of `event` with `A`: its own `on` says so, and `A` is read from it.
					Queue.offerUnsafe(queue, args as unknown as A);
				};
				target.on(event, listener);
				return listener;
			}),
			(listener) => Effect.sync(() => (target.off ?? target.removeListener)?.call(target, event, listener)),
		),
	);
}

/** The part of an event emitter `events` needs. */
interface EventEmitterLike {
	on(event: string, listener: (...args: ReadonlyArray<unknown>) => void): unknown;
	off?(event: string, listener: (...args: ReadonlyArray<unknown>) => void): unknown;
	removeListener?(event: string, listener: (...args: ReadonlyArray<unknown>) => void): unknown;
}
